// Icônes de l'appli (192, 512, 180 px et 512 « maskable »), servies par une fonction car l'éditeur de GitHub ne permet pas d'ajouter de fichiers binaires.
// Générées par parts/brand/mkbrand.py à partir du logo de VenteExpress.
const PNG = {
 "icon-192.png": "",
 "icon-512.png": "",
 "apple-touch-icon.png": "",
 "icon-maskable-512.png": ""
};
export default async (req) => {
  const name = new URL(req.url).pathname.replace(/^\//, "");
  const b64 = PNG[name];
  if (!b64) return new Response("Not found", { status: 404 });
  return new Response(Uint8Array.from(atob(b64), c => c.charCodeAt(0)), { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" } });
};
export const config = { path: ["/icon-192.png", "/icon-512.png", "/apple-touch-icon.png", "/icon-maskable-512.png"] };
